func (q *Queries) SnoozeNextAction(ctx context.Context, arg SnoozeNextActionParams) error {
	_, err := q.db.Exec(ctx, snoozeNextAction, arg.Hours, arg.UserID, arg.RuleID)
	return err
}

const updateNextActionRule = `-- name: UpdateNextActionRule :one
UPDATE next_action_rules SET
    name = $1, description = $2, enabled = $3,
    priority = $4, upsell = $5, audience = $6, conditions = $7,
    payload = $8, channels = $9,
    completion_signal = $10, frequency = $11,
    valid_from = $12, valid_until = $13, updated_at = now()
WHERE id = $14
RETURNING id, slug, name, description, enabled, priority, audience, conditions,
       payload, channels, completion_signal, frequency, valid_from, valid_until,
       created_by, created_at, updated_at, upsell
`

type UpdateNextActionRuleParams struct {
	Name             string             `json:"name"`
	Description      string             `json:"description"`
	Enabled          bool               `json:"enabled"`
	Priority         int32              `json:"priority"`
	Upsell           bool               `json:"upsell"`
	Audience         []byte             `json:"audience"`
	Conditions       []byte             `json:"conditions"`
	Payload          []byte             `json:"payload"`
	Channels         []byte             `json:"channels"`
	CompletionSignal []byte             `json:"completion_signal"`
	Frequency        []byte             `json:"frequency"`
	ValidFrom        pgtype.Timestamptz `json:"valid_from"`
	ValidUntil       pgtype.Timestamptz `json:"valid_until"`
	ID               pgtype.UUID        `json:"id"`
}

func (q *Queries) UpdateNextActionRule(ctx context.Context, arg UpdateNextActionRuleParams) (NextActionRule, error) {
	row := q.db.QueryRow(ctx, updateNextActionRule,
		arg.Name,
		arg.Description,
		arg.Enabled,
		arg.Priority,
		arg.Upsell,
		arg.Audience,
		arg.Conditions,
		arg.Payload,
		arg.Channels,
		arg.CompletionSignal,
		arg.Frequency,
		arg.ValidFrom,
		arg.ValidUntil,
		arg.ID,
	)
	var i NextActionRule
	err := row.Scan(
		&i.ID,
		&i.Slug,
		&i.Name,
		&i.Description,
		&i.Enabled,
		&i.Priority,
		&i.Audience,
		&i.Conditions,
		&i.Payload,
		&i.Channels,
		&i.CompletionSignal,
		&i.Frequency,
		&i.ValidFrom,
		&i.ValidUntil,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Upsell,
	)
	return i, err
}

